// POST /api/anfrage – öffentliches Anfrageformular aller Zielgruppen (Vertrag: docs/BRIEFING.md, docs/API.md)
// Erzeugt einen Vorgang; bei typ flaeche/agri zusätzlich einen Flächen-Entwurf.
//
// Paket C (Welle 1):
//  - Keine Pflicht-Einwilligung mehr: Die Bearbeitung stützt sich auf Art. 6 Abs. 1 lit. b DSGVO, das Formular
//    zeigt dazu einen Hinweis (Text, Version und Hash werden beim Vorgang gespeichert). Optionale, getrennte
//    Einwilligungen (body.einwilligungen = { werbeanruf, newsletter, … } nur true/false) werden je Eintrag mit
//    Version und Text-Hash protokolliert. Texte: src/lib/anfrage/hinweise.js (ENTWURF, Strang R).
//    Ältere Clients mit body.einwilligung = true funktionieren weiter.
//  - Rückruf ausdrücklich gewählt (body.rueckruf = true) → Telefon ist Pflicht (serverseitig geprüft).
//  - Server-Zähler ohne Kennung (src/lib/anfrage/zaehler.js): versuch / angelegt / abgelehnt / honeypot.

import { createHash } from "node:crypto";
import { route } from "@/lib/plattform/server/route";
import { PlattformFehler } from "@/lib/plattform/fehler";
import { HINWEIS, einwilligungenAufbereiten, hinweisText } from "@/lib/anfrage/hinweise";
import { anfrageLand } from "@/lib/anfrage/laender";
import { anfrageZaehlen } from "@/lib/anfrage/zaehler";

const sha256 = (s) => createHash("sha256").update(String(s)).digest("hex");
const objekt = (x) => (x && typeof x === "object" && !Array.isArray(x) ? x : {});

export const POST = route({ auth: "optional", limit: "anfrage", maxBytes: 48 * 1024 }, async ({ body, backend, ip, nutzer }) => {
  const kontakt = objekt(body.kontakt);
  const daten = objekt(body.daten);
  const herkunft = objekt(body.herkunft);
  const merkmale = { typ: body.typ, land: anfrageLand(kontakt, daten), kanal: herkunft.kanal };

  if (body.website) {
    anfrageZaehlen({ ...merkmale, ereignis: "honeypot" });
    return { ok: true, id: "", vorgang: null }; // Honeypot: still verwerfen
  }
  anfrageZaehlen({ ...merkmale, ereignis: "versuch" });

  try {
    const telefon = typeof kontakt.telefon === "string" ? kontakt.telefon.trim() : "";
    const rueckruf = body.rueckruf === true;
    if (rueckruf && !telefon) throw new PlattformFehler(422, "Für einen Rückruf brauchen wir Ihre Telefonnummer.");
    const am = new Date().toISOString();
    const sprache = daten.sprache === "en" ? "en" : "de"; // /en-Formulare zeigen den englischen Wortlaut
    const ergebnis = await backend.anfrageAnlegen({
      typ: body.typ,
      kontakt,
      daten: { ...daten, rueckrufGewuenscht: rueckruf },
      herkunft,
      ip,
      einwilligungText: hinweisText(sprache),
      hinweis: { id: HINWEIS.id, version: HINWEIS.version, rechtsgrundlage: HINWEIS.rechtsgrundlage, textHash: sha256(hinweisText(sprache)) },
      einwilligungen: einwilligungenAufbereiten(body.einwilligungen, { hash: sha256, am, telefon, sprache }),
      nutzer,
    });
    anfrageZaehlen({ ...merkmale, land: ergebnis.vorgang?.land || merkmale.land, ereignis: "angelegt" });
    return { ok: true, id: ergebnis.id, vorgang: ergebnis.vorgang };
  } catch (e) {
    anfrageZaehlen({ ...merkmale, ereignis: "abgelehnt" });
    throw e;
  }
});
// src/lib/anfrage/hinweise.js
//
// Datenschutz-Hinweis und optionale Einwilligungen im Anfrageformular (Paket C, Welle 1).
//
// ┌─────────────────────────────────────────────────────────────────────────────────────────────┐
// │ ENTWURF – KEINE FREIGABE. Alle Texte in dieser Datei sind Platzhalter des Agenten-Teams.      │
// │ Den finalen Wortlaut liefert Strang R (Rechtstexte, Anwalt). Bis dahin: Seite nicht öffentlich │
// │ bzw. noindex. Jede Textänderung → VERSION erhöhen (der Hash wird je Eintrag gespeichert).      │
// └─────────────────────────────────────────────────────────────────────────────────────────────┘
//
// Rechtliche Linie laut Masterplan Abschnitt 5 (zu prüfen durch Strang R):
//  - Die Bearbeitung der Anfrage stützt sich auf Art. 6 Abs. 1 lit. b DSGVO (vorvertragliche Maßnahme auf
//    Anfrage) – dafür wird KEINE Einwilligung verlangt, sondern informiert (Hinweis, kein Pflicht-Häkchen).
//  - Ein ausdrücklich gewählter Rückruf ist Teil der Anfrage (lit. b); die Nummer wird nur dafür genutzt.
//  - Werbeanrufe und Werbe-Mails nur mit eigener, nicht vorbelegter Einwilligung
//    (DE § 7 UWG; AT § 174 TKG 2021, auch B2B; CH Art. 3 Abs. 1 lit. o UWG) – drei getrennte Häkchen.
//  - Die Weitergabe an Partner setzt benannte Partner voraus; solange keine benannt sind, bleibt das
//    Häkchen ausgeblendet (aktiv: false).

export const HINWEIS_VERSION = "ENTWURF-2026-10-03";

/** Hinweis statt Pflicht-Einwilligung (der vollständige Text wird mit Version und Hash beim Vorgang gespeichert) */
const HINWEIS_KERN = "Wir verarbeiten Ihre Angaben, um Ihre Anfrage zu beantworten. Eine Einwilligung ist dafür nicht nötig.";
const HINWEIS_VERWEIS_VOR = "Einzelheiten und Ihre Rechte finden Sie in der";
const HINWEIS_VERWEIS_LINK = "Datenschutzerklärung";
export const HINWEIS = Object.freeze({
  id: "hinweis_anfrage",
  rechtsgrundlage: "Art. 6 Abs. 1 lit. b DSGVO",
  version: HINWEIS_VERSION,
  kern: HINWEIS_KERN,
  verweisVor: HINWEIS_VERWEIS_VOR,
  verweisLink: HINWEIS_VERWEIS_LINK, // Link auf /datenschutz
  text: `${HINWEIS_KERN} ${HINWEIS_VERWEIS_VOR} ${HINWEIS_VERWEIS_LINK}.`,
  // Englische Seiten (/en): eigener Wortlaut, eigener Hash
  en: Object.freeze({
    kern: "We process your details to answer your enquiry. No consent is needed for this.",
    verweisVor: "Details and your rights are set out in our",
    verweisLink: "privacy policy (in German)",
    text: "We process your details to answer your enquiry. No consent is needed for this. Details and your rights are set out in our privacy policy (in German).",
  }),
});

/** Rückruf-Wunsch (Teil der Anfrage, keine Werbeeinwilligung) */
export const RUECKRUF = Object.freeze({
  id: "rueckruf",
  version: HINWEIS_VERSION,
  text: "Bitte rufen Sie mich zu dieser Anfrage zurück.",
  zusatz: "Dann brauchen wir Ihre Telefonnummer. Wir nutzen sie nur für diese Anfrage.",
  en: Object.freeze({ text: "Please call me back about this enquiry.", zusatz: "We then need your phone number. We use it only for this enquiry." }),
});

/**
 * Optionale, getrennte Einwilligungen – nie vorbelegt, nie Voraussetzung für die Anfrage.
 *  nurMitTelefon: nur anzeigen, wenn das Formular ein Telefonfeld hat
 *  aktiv: false → nicht anzeigen und serverseitig nicht annehmen
 */
export const EINWILLIGUNGEN = Object.freeze([
  Object.freeze({
    id: "werbeanruf",
    version: HINWEIS_VERSION,
    nurMitTelefon: true,
    aktiv: true,
    text: "Ja, ÖkoInvest darf mich auch später telefonisch zu passenden eigenen Angeboten ansprechen. Ich kann das jederzeit widerrufen.",
    textEn: "Yes, ÖkoInvest may also call me later about suitable offers of its own. I can withdraw this at any time.",
  }),
  Object.freeze({
    id: "newsletter",
    version: HINWEIS_VERSION,
    nurMitTelefon: false,
    aktiv: true,
    // TODO Strang R + Betrieb: Double-Opt-in-Strecke fehlt noch – bis dahin wird nur der Wunsch gespeichert (doi: "ausstehend"), es geht nichts raus.
    text: "Ja, ich möchte Fachinformationen und Fristen-Hinweise für mein Land per E-Mail erhalten. Die Anmeldung bestätige ich per E-Mail; Abmeldung jederzeit.",
    textEn: "Yes, I would like to receive market information and deadline alerts for my country by e-mail. I will confirm by e-mail; unsubscribe at any time.",
  }),
  Object.freeze({
    id: "partner",
    version: HINWEIS_VERSION,
    nurMitTelefon: false,
    aktiv: false, // TODO Strang R: Partner namentlich benennen, erst dann einschalten
    text: "Ja, meine Anfrage darf an folgende Partner weitergegeben werden: [Partnerliste folgt – Strang R].",
    textEn: "Yes, my enquiry may be passed on to the following partners: [partner list to follow].",
  }),
]);

export const EINWILLIGUNG_IDS = Object.freeze(EINWILLIGUNGEN.filter((e) => e.aktiv).map((e) => e.id));

/** Wortlaut je Sprache (Standard Deutsch) */
export const einwilligungText = (e, sprache) => (sprache === "en" && e.textEn ? e.textEn : e.text);
export const hinweisText = (sprache) => (sprache === "en" ? HINWEIS.en.text : HINWEIS.text);

/** Für das Formular: welche Häkchen werden angezeigt? */
export function einwilligungenFuer({ mitTelefon }) {
  return EINWILLIGUNGEN.filter((e) => e.aktiv && (!e.nurMitTelefon || mitTelefon));
}

/**
 * Eingabe des Formulars → Protokoll-Einträge (nur erteilte, nur bekannte, nur aktive).
 * hash: Funktion text → Hex-Hash (Server: SHA-256); am: Zeitstempel (ISO).
 * Telefon-Einwilligung ohne Telefonnummer wird verworfen. sprache: "en" → Hash über den englischen Wortlaut.
 */
export function einwilligungenAufbereiten(eingabe, { hash, am, telefon, sprache }) {
  const roh = eingabe && typeof eingabe === "object" && !Array.isArray(eingabe) ? eingabe : {};
  const out = [];
  for (const e of EINWILLIGUNGEN) {
    if (!e.aktiv || roh[e.id] !== true) continue;
    if (e.nurMitTelefon && !telefon) continue;
    out.push({ id: e.id, erteilt: true, am, version: e.version, sprache: sprache === "en" ? "en" : "de", textHash: hash(einwilligungText(e, sprache)), ...(e.id === "newsletter" ? { doi: "ausstehend" } : {}) });
  }
  return out;
}
// src/lib/anfrage/laender.js
//
// Länderlogik für Anfragen (Paket C, Welle 1): Land aus dem Kontext bestimmen, PLZ-Regel je Land,
// länderrichtige Begriffe. Reine Funktionen ohne React und ohne Server-Abhängigkeiten – genutzt vom
// Anfrageformular (Client), vom Demo-Backend (Server) und von den Tests. Die Frappe-Seite spiegelt
// dieselbe Logik in Backend-Import/…/plattform/api/anfrage.py (_land_bestimmen).

export const ANFRAGE_LAENDER = Object.freeze(["DE", "AT", "CH"]);

/** PLZ-Muster je Land: DE 5 Ziffern, AT 4 Ziffern, CH 4 Ziffern */
export const PLZ_MUSTER = Object.freeze({ DE: /^\d{5}$/, AT: /^\d{4}$/, CH: /^\d{4}$/ });
export const PLZ_BEISPIEL = Object.freeze({ DE: "86825", AT: "5020", CH: "8001" });

/** "at", " CH " → "AT" | "CH"; alles andere → "" */
export function landNormal(wert) {
  const s = typeof wert === "string" ? wert.trim().toUpperCase() : "";
  return ANFRAGE_LAENDER.includes(s) ? s : "";
}

/** Land aus fachlichen Zusatzdaten: Regionsseiten schicken daten.land, der Flächencheck daten.eingaben.land */
export function landAusDaten(daten) {
  if (!daten || typeof daten !== "object") return "";
  return landNormal(daten.land) || landNormal(daten.eingaben?.land) || "";
}

/**
 * Land einer Anfrage, in dieser Reihenfolge:
 *  1. ausdrücklich gewähltes bzw. übergebenes Land (kontakt.land)
 *  2. Land aus dem Kontext der Seite (daten.land / daten.eingaben.land)
 *  3. eindeutige PLZ: nur 5 Ziffern sind eindeutig (Deutschland); 4 Ziffern können AT oder CH sein → offen
 * Ergebnis "" heißt: Land unbekannt.
 */
export function anfrageLand(kontakt, daten) {
  const direkt = landNormal(kontakt?.land) || landAusDaten(daten);
  if (direkt) return direkt;
  const plz = String(kontakt?.plz ?? "").trim();
  return PLZ_MUSTER.DE.test(plz) ? "DE" : "";
}

/** Passt die PLZ zum Land? Leere PLZ ist immer in Ordnung (Feld ist optional). Unbekanntes Land: 4 oder 5 Ziffern. */
export function plzPasst(land, plz) {
  const s = String(plz ?? "").trim();
  if (!s) return true;
  const l = landNormal(land);
  if (l) return PLZ_MUSTER[l].test(s);
  return /^\d{4,5}$/.test(s);
}

/** Begriff für das Grundstück im Kataster – „Flurstück“ gibt es nur in Deutschland */
export const GRUNDSTUECK = Object.freeze({
  DE: { einzahl: "Flurstück", mehrzahl: "Flurstücke", genau: "flurstückgenau" },
  AT: { einzahl: "Grundstücksnummer", mehrzahl: "Grundstücke", genau: "grundstücksgenau" },
  CH: { einzahl: "Parzelle", mehrzahl: "Parzellen", genau: "parzellengenau" },
});
export const grundstueck = (land) => GRUNDSTUECK[landNormal(land)] || { einzahl: "Flurstück bzw. Grundstücksnummer/Parzelle", mehrzahl: "Flurstücke bzw. Grundstücke/Parzellen", genau: "grundstücksgenau" };

/** Wizard-Nutzung → Nutzungsschlüssel der Fläche im Backend (konstanten.js FLAECHE_NUTZUNG) */
export const NUTZUNG_ALIAS = Object.freeze({ parkplatz: "gewerbe", deponie: "sonstige" });
// src/lib/anfrage/zaehler.js
//
// Server-Zähler für Anfragen OHNE Kennung (Paket C, Welle 1; Masterplan Abschnitt 5 Punkt 6).
// Zählt unabhängig von Cookie-Einwilligung und Google Analytics, weil nichts Personenbezogenes entsteht:
// gezählt wird nur je Tag × Ereignis × Anfragetyp × Land × Kanal. KEINE IP, KEINE E-Mail, KEINE Vorgangs-ID,
// keine Seiten-URL, kein Zeitstempel feiner als der Tag.
//
// Ausgabe: (1) Summen im Arbeitsspeicher des Prozesses (zaehlerStand) und (2) je Ereignis eine
// strukturierte Logzeile „[anfrage-zaehler] {…}“, die das Hosting-Log aufbewahrt und auswertbar macht.
// Dauerhaft gezählt wird zusätzlich im Backend (Demo: db.anfrageZaehler; Frappe: Logger „oekoinvest_anfrage_zaehler“).

import { landNormal } from "./laender.js";

export const ZAEHLER_EREIGNISSE = Object.freeze(["versuch", "angelegt", "abgelehnt", "honeypot"]);
// Kanäle wie in src/lib/herkunft.js (kanal())
const KANAELE = new Set(["Direkt", "Suchmaschine", "KI-Assistent", "Anzeige", "Social Media", "E-Mail", "Offline/QR", "Kampagne", "Verweis"]);
const TYP_MUSTER = /^[a-z_]{2,30}$/;

const summen = new Map();

/** Tag in Europe/Vienna (gleiche Zeitzone wie das Backoffice), Format JJJJ-MM-TT */
export const tagHeute = (d = new Date()) => d.toLocaleDateString("sv-SE", { timeZone: "Europe/Vienna" });

/** Nur grobe, feste Merkmale – alles Unbekannte wird zu "?" */
export function zaehlerSchluessel({ ereignis, typ, land, kanal, tag = tagHeute() }) {
  return {
    tag,
    ereignis: ZAEHLER_EREIGNISSE.includes(ereignis) ? ereignis : "?",
    typ: typeof typ === "string" && TYP_MUSTER.test(typ) ? typ : "?",
    land: landNormal(land) || "?",
    kanal: typeof kanal === "string" && KANAELE.has(kanal) ? kanal : "?",
  };
}

/** Zählt ein Ereignis. Darf nie werfen (Messung stört keine Anfrage). */
export function anfrageZaehlen(merkmale, { log = true } = {}) {
  try {
    const s = zaehlerSchluessel(merkmale || {});
    const k = `${s.tag}|${s.ereignis}|${s.typ}|${s.land}|${s.kanal}`;
    summen.set(k, (summen.get(k) || 0) + 1);
    if (log) console.info(`[anfrage-zaehler] ${JSON.stringify(s)}`);
    return s;
  } catch {
    return null;
  }
}

/** Aktuelle Summen dieses Prozesses (für Tests und eine spätere Auswertungsroute) */
export function zaehlerStand() {
  return Object.fromEntries(summen);
}

export function _zaehlerLeeren() {
  summen.clear();
}
// src/lib/plattform/hashkette.js
//
// Revisionssicheres Aktivitätsprotokoll: Hash-Kette über alle Einträge.
//
//   hash_n = SHA-256( prevHash_n + "\n" + inhalt_n )      mit prevHash_n = hash_(n-1)
//
// `inhalt` ist eine kanonische JSON-Darstellung der fachlichen Felder in fester Reihenfolge
// (id, am, nutzerId, aktion, objektArt, objektId, text, ip). Wer einen Eintrag nachträglich ändert,
// löscht, einfügt oder umsortiert, bricht die Kette ab dieser Stelle – verifyChain() meldet die
// erste Abweichung. Identisches Verfahren in Frappe: plattform/hashkette.py (Feld prev_hash/entry_hash).
//
// Werden alte Einträge archiviert (Demo: > 5000 Einträge), bleibt ein Anker { hash, anzahl, bis }
// stehen: die Prüfung beginnt dann beim Anker-Hash statt beim Startwert.
//
// Nur serverseitig (node:crypto).

import { createHash } from "node:crypto";

export const KETTE_START = "0".repeat(64);
export const KETTE_FELDER = ["id", "am", "nutzerId", "aktion", "objektArt", "objektId", "text", "ip"];

const wert = (v) => (v === undefined || v === null ? "" : String(v));

/** Kanonischer Inhalt eines Eintrags (unabhängig von zusätzlichen Feldern wie `nutzer`) */
export function eintragInhalt(e) {
  return JSON.stringify(KETTE_FELDER.map((k) => [k, wert(e?.[k])]));
}

export function eintragHash(prevHash, e) {
  return createHash("sha256").update(`${prevHash}\n${eintragInhalt(e)}`, "utf8").digest("hex");
}

/** Eintrag an die Kette anhängen: setzt prevHash und hash (verändert das Objekt) */
export function verketten(e, prevHash = KETTE_START) {
  e.prevHash = prevHash || KETTE_START;
  e.hash = eintragHash(e.prevHash, e);
  return e;
}

/**
 * Kette prüfen. `eintraege` in Einfügereihenfolge (älteste zuerst).
 * Liefert { ok, geprueft, fehler: [{ index, id, grund }], letzterHash, start }.
 * Mit `alleFehler: false` (Standard) endet die Prüfung beim ersten Bruch.
 */
export function verifyChain(eintraege = [], { anker = null, alleFehler = false } = {}) {
  const start = anker?.hash || KETTE_START;
  let prev = start;
  const fehler = [];
  let geprueft = 0;
  for (let i = 0; i < eintraege.length; i++) {
    const e = eintraege[i];
    geprueft++;
    let grund = "";
    if (!e?.hash) grund = "Eintrag ohne Hash (ungesichert eingefügt)";
    else if (e.prevHash !== prev) grund = "Verweis auf den Vorgänger passt nicht (Eintrag gelöscht, eingefügt oder umsortiert)";
    else if (eintragHash(prev, e) !== e.hash) grund = "Inhalt wurde nachträglich verändert";
    if (grund) {
      fehler.push({ index: i, id: e?.id || null, am: e?.am || null, grund });
      if (!alleFehler) break;
    }
    prev = e?.hash || prev;
  }
  return { ok: fehler.length === 0, geprueft, anzahl: eintraege.length, fehler, letzterHash: prev, start };
}

/** Python-Name wie in Frappe (plattform/hashkette.py) */
export const verify_chain = verifyChain;
// src/lib/plattform/backend/werkzeuge.js
//
// Backend-Teil „Backoffice-Werkzeuge“ (Team 8: Transaktion, Compliance, Buchhaltung) – eigene Schnittstelle,
// backend/index.js bleibt unverändert. Auswahl wie backend(): Frappe bei PLATTFORM_BACKEND=frappe, sonst Demo.
//
// Operationen (n = angemeldeter Nutzer):
//   Buchhaltung  bhUebersicht(n) · bhEinstellungenSpeichern(n,{mahnwesen,konten}) · bhMahnlauf(n,{ids,trockenlauf})
//                bhMahnsperre(n,belegId,{bis,grund}) · bhStorno(n,belegId,{grund,provisionStornieren})
//                bhBelegDokument(n,belegId,{art:"mahnung"|"storno",nr,ip}) · bhMeineDokumente(n)
//                bhZahlungImport(n,{inhalt,dateiname,format}) · bhZahlungAktion(n,id,{aktion,belegId,grund})
//                bhExport(n,{format:"datev"|"bmd"|"op",von,bis}) · bhAbschluss(n,monat) · bhAbschlussAktion(n,monat,{aktion,punkt,erledigt,notiz,grund})
//   Datenschutz  dsUebersicht(n,{status}) · dsAnlegen(n,daten) · dsAktion(n,id,{aktion,…}) · dsExport(n,id,{ip}) · vvtExport(n,{format})
//                kycSlaUebersicht(n)
//   GwG          verdachtListe(n,{status}) · verdachtMelden(n,daten) · verdachtAktion(n,id,{aktion,…})
//   Transaktion  dealPipeline(n,{land,phase}) · dealPrognose(n,projektId,{wahrscheinlichkeit,closingErwartet,notiz}) · dealBericht(n,filter)
//
// Nur serverseitig verwenden.

import * as bh from "./demo/buchhaltung";
import * as ds from "./demo/datenschutz";
import * as tr from "./demo/transaktion";
import * as frappe from "./frappe/werkzeuge";
import { backendName, KONFIG_FEHLER } from "./index";
import { PlattformFehler } from "../fehler";

const demo = { ...bh, ...ds, ...tr };

export const WERKZEUG_OPERATIONEN = [
  "bhUebersicht", "bhEinstellungenSpeichern", "bhMahnlauf", "bhMahnsperre", "bhStorno", "bhBelegDokument", "bhMeineDokumente", "bhZahlungImport", "bhZahlungAktion",
  "bhExport", "bhAbschluss", "bhAbschlussAktion", "dsUebersicht", "dsAnlegen", "dsAktion", "dsExport", "vvtExport", "kycSlaUebersicht", "verdachtListe",
  "verdachtMelden", "verdachtAktion", "dealPipeline", "dealPrognose", "dealBericht",
];

if (process.env.NODE_ENV !== "production") {
  for (const [name, impl] of [["demo", demo], ["frappe", frappe]]) {
    const fehlt = WERKZEUG_OPERATIONEN.filter((op) => typeof impl[op] !== "function");
    if (fehlt.length) console.warn(`[plattform] Backoffice-Werkzeuge ${name}: fehlende Operationen ${fehlt.join(", ")}`);
  }
}

export function werkzeugeBackend() {
  const n = backendName();
  if (n === "frappe") return frappe;
  if (n === "demo") return demo;
  throw new PlattformFehler(503, KONFIG_FEHLER);
}

