          else assert.equal(r.zustaendigId, null, "inaktiv oder kein Gebiet → ohne Zuständigkeit");
        }
      }
    }
  }
  assert.equal(n, 5 * LEAD_TYP_IDS.length * GROESSEN_KLASSEN.length * 3);
});

