            </li>
          ))}
        </ul>
        <ul className="mt-4 space-y-1 text-[12.5px] text-ink-600">
          {d.todo.map((t) => <li key={t}>• {t}</li>)}
        </ul>
      </Karte>
    </div>
  );
}

